def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]

    # Check all possible positions for the '*' to match
    for i in range(len(s) - len(prefix) + 1):
        if s[i:i + len(prefix)] == prefix:
            # Check if the remaining part of s can match the suffix after '*'
            if s[i + len(prefix):].endswith(suffix):
                return True
            # Check for additional characters between prefix and suffix
            for j in range(len(s) - (i + len(prefix)) + 1):
                if s[i + len(prefix):][j:j + len(suffix)] == suffix:
                    return True

    return False

