def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return n  # trivial case

    dp = [1] * n  # dp[i] will hold the length of the longest subsequence ending at index i
    max_length = 1

    for i in range(n):
        for j in range(i):
            diff_ij = abs(nums[i] - nums[j])  # absolute difference between nums[i] and nums[j]
            if j == 0 or (abs(nums[j] - nums[j - 1]) >= diff_ij):
                dp[i] = max(dp[i], dp[j] + 1)
                max_length = max(max_length, dp[i])

    return max_length

