def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0] * 3 for _ in range(n)]
    dp[0] = cost[0]

    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(
                dp[i-1][(j+1) % 3],
                dp[i-1][(j+2) % 3]
            )

    total_cost = float('inf')
    for j in range(3):
        total_cost = min(total_cost, dp[n-1][j])

    # Check for equidistant house constraints
    for j in range(3):
        # Backward checking for houses at positions n-1 and 0
        if dp[n-1][j] < total_cost:
            for k in range(3):
                if j != k and j != (n // 2 + k) % 3:
                    total_cost = min(total_cost, dp[n-1][j])

    return total_cost

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in events:
        event_type, timestamp, *args = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(args[0])
            online[user_id] = False
            offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            # Update online status for users who may come back online
            for user_id in range(numberOfUsers):
                if not online[user_id] and timestamp >= offline_until[user_id]:
                    online[user_id] = True

            mentions_string = args[0]
            if mentions_string == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == "HERE":
                for i in range(numberOfUsers):
                    if online[i]:
                        mentions[i] += 1
            else:
                for mention in mentions_string.split():
                    if mention.startswith("id"):
                        user_id = int(mention[2:])
                        mentions[user_id] += 1

    return mentions

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0
    moves = []
    for move in s:
        if move == 'N':
            y += 1
        elif move == 'S':
            y -= 1
        elif move == 'E':
            x += 1
        elif move == 'W':
            x -= 1
        current_distance = abs(x) + abs(y)
        max_distance = max(max_distance, current_distance)
        moves.append((x, y))
        k -= min(k, abs(x) + abs(y) - current_distance)
        if k < 0:
            break
    # The best we can do with k additional changes is to extend the maximum distance calculated.
    return max_distance + k
